INSERT INTO PPM_DEPKPI_DEP_CHECK (
ID , SUGGEST , DEPID , TARGETID , PARENTID , BASEPOINT , HASSON , SIGN , NAME , REMARK , LEVELNUM , TARGETTYPE , EVALTYPE , SELFEVAL , MAXPOINT , MINPOINT , TYEAR , STATUS , DBUSER , MARKERDEPID ,
) VALUES(
#{id} , #{suggest} , #{depid} , #{targetid} , #{parentid} , #{basepoint} , #{hasson} , #{sign} , #{name} , #{remark} , #{levelnum} , #{targettype} , #{evaltype} , #{selfeval} , #{maxpoint} , #{minpoint} , #{tyear} , #{status} , #{dbuser} , #{markerdepid} ,
)

mapper.update:
UPDATE PPM_DEPKPI_DEP_CHECK
SUGGEST=#{suggest} , DEPID=#{depid} , TARGETID=#{targetid} , PARENTID=#{parentid} , BASEPOINT=#{basepoint} , HASSON=#{hasson} , SIGN=#{sign} , NAME=#{name} , REMARK=#{remark} , LEVELNUM=#{levelnum} , TARGETTYPE=#{targettype} , EVALTYPE=#{evaltype} , SELFEVAL=#{selfeval} , MAXPOINT=#{maxpoint} , MINPOINT=#{minpoint} , TYEAR=#{tyear} , STATUS=#{status} , DBUSER=#{dbuser} , MARKERDEPID = #{markerdepid} ,
WHERE ID=#{id}

UPDATE
PPM_DEPKPI_DEP_CHECK
set STATUS=#{status}, DBUSER=#{dbuser}
WHERE ID=#{id}

